exercise.referenceSolution:
struct Base { virtual int read() const { return 1; } virtual ~Base() = default; };
class Derived : public Base { int value_; public: explicit Derived(int x) : value_(x) {} int read() const override { return value_; } };
int consumer(const Base& source) { return source.read(); }
int solve(int a,int b) { Derived d{a}; return consumer(d)+b; }
